param([string]$Root="C:\pinchbench-grok-build",[string]$RunDir="",[string]$OutputDirectory="$HOME\Downloads")
$ErrorActionPreference="Stop";if(-not$RunDir){$RunDir=(Get-ChildItem (Join-Path $Root "runs") -Directory -Filter "grok_build_*"|Sort-Object LastWriteTime -Descending|Select-Object -First 1).FullName};if(-not$RunDir){throw "No run found"};$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$stage=Join-Path $env:TEMP "grok_build_run_diag_$stamp";$zip=Join-Path $OutputDirectory "grok_build_run_diagnostic_$stamp.zip";Remove-Item $stage,$zip -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force $stage|Out-Null
foreach($name in @("run_config.json","progress.jsonl","results.partial.json","results.json","results.csv","results.xlsx","heartbeat.json")){if(Test-Path (Join-Path $RunDir $name)){Copy-Item (Join-Path $RunDir $name) $stage -Force}}
foreach($dir in @("judge_raw_responses","transcripts")){if(Test-Path (Join-Path $RunDir $dir)){Copy-Item (Join-Path $RunDir $dir) $stage -Recurse -Force}}
Copy-Item (Join-Path $Root "runner\SHA256SUMS.txt") $stage -Force -ErrorAction SilentlyContinue;Copy-Item (Join-Path $Root "logs\search-adapter.jsonl") $stage -Force -ErrorAction SilentlyContinue;Compress-Archive (Join-Path $stage "*") $zip -Force;Get-Item $zip|Select-Object FullName,Length;Get-FileHash $zip -Algorithm SHA256
